function mean(xs) {
  return xs.reduce((sum, x) => sum + x, 0) / xs.length;
}

function sumSquaredGaps(xs) {
  const m = xs.reduce((sum, x) => sum + x, 0) / xs.length;
  return xs.reduce((sum, x) => sum + (x - m) ** 2, 0);
}

function sampleVariance(xs) {
  const m = xs.reduce((sum, x) => sum + x, 0) / xs.length;
  const total = xs.reduce((sum, x) => sum + (x - m) ** 2, 0);
  return total / (xs.length - 1);
}

function sampleStdDev(xs) {
  const m = xs.reduce((sum, x) => sum + x, 0) / xs.length;
  const total = xs.reduce((sum, x) => sum + (x - m) ** 2, 0);
  const sd = Math.sqrt(total / (xs.length - 1));
  return Math.round(sd * 100) / 100;
}

function standardError(sd, n) {
  return Math.round((sd / Math.sqrt(n)) * 100) / 100;
}

function rate(conversions, visitors) {
  return conversions / visitors;
}

