function isSignificant(x1, n1, x2, n2) {
  const pooled = (x1 + x2) / (n1 + n2);
  const se = Math.sqrt(pooled * (1 - pooled) * (1 / n1 + 1 / n2));
  const z = (x2 / n2 - x1 / n1) / se;
  return Math.abs(z) >= 1.96;
}

function proportionInterval(x, n) {
  const p = x / n;
  const half = 1.96 * Math.sqrt((p * (1 - p)) / n);
  const round3 = (v) => Math.round(v * 1000) / 1000;
  return [round3(p - half), round3(p + half)];
}

function smallestGroupSize(rate1, rate2) {
  for (let n = 50; n <= 20000; n += 10) {
    const x1 = Math.round(rate1 * n);
    const x2 = Math.round(rate2 * n);
    const pooled = (x1 + x2) / (2 * n);
    const se = Math.sqrt(pooled * (1 - pooled) * (2 / n));
    if (se > 0 && Math.abs((x2 - x1) / n / se) >= 1.96) return n;
  }
  return null;
}
